CHANNELS = ('amazon', 'flipkart', 'myntra')


def parse_lines(csv_text):
    lines = [ln for ln in csv_text.splitlines() if ln.strip()]
    if not lines:
        return []
    header = [h.strip().lower() for h in lines[0].split(',')]
    return [dict(zip(header, (p.strip() for p in ln.split(',')))) for ln in lines[1:]]


def _is_positive_int(text):
    try:
        return int(text) >= 1
    except ValueError:
        return False


def _is_non_negative_number(text):
    try:
        return float(text) >= 0
    except ValueError:
        return False


def validate_row(row):
    errors = []
    if not row.get('order_id'):
        errors.append('order_id: required')
    if not _is_positive_int(row.get('qty', '')):
        errors.append('qty: must be a positive integer')
    if not _is_non_negative_number(row.get('unit_price', '')):
        errors.append('unit_price: must be a number >= 0')
    channel = row.get('channel', '')
    if channel.lower() not in CHANNELS:
        errors.append(f"channel: unknown '{channel}'")
    return errors


def transform_row(row):
    qty = int(row['qty'])
    price = float(row['unit_price'])
    return {
        'order_id': row['order_id'],
        'sku': row.get('sku', '').upper(),
        'qty': qty,
        'unit_price': price,
        'channel': row['channel'].lower(),
        'line_total': round(qty * price, 2),
    }


def process_report(csv_text):
    rows, rejected = [], []
    for line_no, row in enumerate(parse_lines(csv_text), start=1):
        errors = validate_row(row)
        if errors:
            rejected.append({'line': line_no, 'errors': errors})
        else:
            rows.append(transform_row(row))
    return {'rows': rows, 'rejected': rejected}


